 if a.get('change_type')=='full_repeal':assert text.startswith(('Le présent article est abrogé','Abrogé'))
 else:
  refs=lambda t:set(re.findall(r'\\bL\\.?\\s*\\d+(?:-\\d+)+',t))
  normalize=lambda r:re.sub(r'[.\\s]','',r)
  missing={normalize(v) for v in refs(s['source_xml'])}-{normalize(v) for v in refs(a['proposed_xml'])}
