 assert s['source_xml'].count('<table')==0
print('24 articles : schéma, identifiants, XML, renvois conservés et métadonnées vérifiés.')
print('Abrogations :',sum(a.get('change_type')=='full_repeal' for a in answer))
print('Réductions normatives :',sum(a.get('change_type')=='normative_reduction' for a in answer))
print('Réécritures à droit constant :',sum('change_type' not in a for a in answer))
print('answer.json :',Path('answer.json').stat().st_size,'octets')
